# ---- Palette: name -> xterm-256 code (RGB derived, never hand-written) -------
PAL = {
    "darkred":    124, "red":        167, "medred":     210, "ltred":      174,
    "dorange":    214, "ltyellow":   220, "dgreen":     192, "black":       16,
    "white":      231, "violet":      93, "blue":        21, "grey":       244,
    "dark_grey":  238, "cyan":        51, "zone_ext":    88, "zone_dmz":   130,
    "zone_int":    22,
}

def xterm_rgb(code):
    if code < 16:
        base = [(0,0,0),(128,0,0),(0,128,0),(128,128,0),(0,0,128),(128,0,128),
                (0,128,128),(192,192,192),(128,128,128),(255,0,0),(0,255,0),
                (255,255,0),(0,0,255),(255,0,255),(0,255,255),(255,255,255)]
        return base[code]
    if code < 232:
        c = code - 16; lv = [0, 95, 135, 175, 215, 255]
        return (lv[c // 36], lv[(c // 6) % 6], lv[c % 6])
    v = 8 + (code - 232) * 10
    return (v, v, v)

LINECHARS = set("─│┌┐└┘├┤┬┴┼►◄▲▼")

class Canvas:
    def __init__(self, lines):
        self.lines = lines
        self.rows = len(lines)
        self.width = max((len(l) for l in lines), default=0)
        self.bg = [[None] * self.width for _ in range(self.rows)]
        self.fg = [[None] * self.width for _ in range(self.rows)]
    def _ch(self, r, c):
        ln = self.lines[r]; return ln[c] if c < len(ln) else " "
    def fill(self, r0, r1, c0, c1, colour):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if 0 <= r < self.rows and 0 <= c < self.width: self.bg[r][c] = colour
    def ink(self, r0, r1, c0, c1, colour, only_lines=False):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if not (0 <= r < self.rows and 0 <= c < self.width): continue
                if only_lines and self._ch(r, c) not in LINECHARS: continue
                self.fg[r][c] = colour
    def box_draw(self, r0, r1, c0, c1, fill, border, text=None):
        self.fill(r0, r1, c0, c1, fill)
        self.ink(r0, r1, c0, c1, text if text is not None else border)
        self.ink(r0, r0, c0, c1, border); self.ink(r1, r1, c0, c1, border)
        self.ink(r0, r1, c0, c0, border); self.ink(r0, r1, c1, c1, border)
    def line(self, r0, r1, c0, c1, colour):
        self.ink(r0, r1, c0, c1, colour, only_lines=True)
    def label(self, r0, r1, c0, c1, colour, bg=None):
        self.ink(r0, r1, c0, c1, colour)
        if bg is not None: self.fill(r0, r1, c0, c1, bg)

