# ---- Generic fallback colouriser: use for any map without a bespoke draw ----
_IP4_RE = re.compile(r'\d{1,3}(?:\.\d{1,3}){3}(?:/\d{1,2})?')
_IP6_RE = re.compile(r'(?:[0-9A-Fa-f]{1,4}:){2,7}[0-9A-Fa-f]{0,4}(?:/\d{1,3})?'
                     r'|::(?:[0-9A-Fa-f]{1,4}:?){1,7}')
def draw_generic(cv):
    """No coordinates needed — colours borders white, IPv4 violet, IPv6 blue.
    Good enough for a newly-supplied map until you write a bespoke draw."""
    cv.ink(0, cv.rows - 1, 0, cv.width - 1, "white", only_lines=True)
    for r, ln in enumerate(cv.lines):
        for m in _IP6_RE.finditer(ln):
            if ':' in m.group(): cv.ink(r, r, m.start(), m.end() - 1, "blue")
        for m in _IP4_RE.finditer(ln):
            cv.ink(r, r, m.start(), m.end() - 1, "violet")

# =============================================================================
#  REGISTRY  —  which map + overlay each activity uses.
#  All activities currently reuse the DMZ map + bespoke overlay. When you paste
#  a new per-week map, set MAPS[act] = <your map> AND DRAWS[act] = draw_generic
#  (or a custom draw_<act>) so the overlay matches.
# =============================================================================
MAPS = {
    "1":   MAP_1,
    "2.1": MAP_2_1,
    "2.2": MAP_2_2,
    "3":   MAP_3,
    "4.1": MAP_4_1,
    "4.2": MAP_4_2,
}
# Activities 1/2.1/2.2/3/4.1 share the DMZ box/route layout (only extra service
# labels inside boxes) -> the bespoke draw_dmz overlay lines up. Activity 4.2
# changes the geometry (VPN client box + tun0), so it uses the generic colouriser.
DRAWS = { "4.2": draw_generic }            # per-activity overlay overrides; default = draw_dmz

def _map_for(activity):   return MAPS.get(activity, MAP_1)
def _draw_for(activity):  return DRAWS.get(activity, draw_dmz)

# =============================================================================
def to_ansi(map_lines, draw_fn):
    cv = Canvas(map_lines); draw_fn(cv)
    width = cv.width
    out = []
    for r, line in enumerate(map_lines):
        s = []
        for c in range(width):
            ch = line[c] if c < len(line) else " "
            b, f = cv.bg[r][c], cv.fg[r][c]
            codes = ""
            if b is not None: codes += "\033[48;5;%dm" % PAL[b]
            if f is not None: codes += "\033[38;5;%dm" % PAL[f]
            s.append(codes + ch + "\033[0m" if codes else ch)
        out.append("".join(s))
    return out, width

def _term_size():
    cols = rows = None
    if len(sys.argv) >= 3:
        try: cols, rows = int(sys.argv[1]), int(sys.argv[2])
        except ValueError: pass
    if not cols or cols <= 0:
        sz = shutil.get_terminal_size(fallback=(190, 40)); cols, rows = sz.columns, sz.lines
    return cols, rows

def render(activity):
    cols, rows = _term_size()
    map_lines = _map_for(activity).strip("\n").split("\n")
    body, width = to_ansi(map_lines, _draw_for(activity))
    pad = " " * max(0, (cols - width) // 2)
    top = max(0, (rows - len(body)) // 2)
    return "\n".join([""] * top + [pad + line for line in body])

if __name__ == "__main__":
    # argv: [COLS ROWS ACTIVITY]  (ACTIVITY optional; defaults to "1")
    activity = sys.argv[3] if len(sys.argv) >= 4 else "1"
    if activity not in MAPS: activity = "1"
    sys.stdout.write(render(activity) + "\n")
